#!/usr/bin/env bash
# Put MatchLens online for free on GitHub Pages (no Azure sign-in, no card).
# The demo replays your AI-explained match in the browser. Run from the matchsim folder:
#   bash deploy_pages.sh
set -u
cd "$(dirname "$0")"
ROOT="$(git rev-parse --show-toplevel 2>/dev/null)" || { echo "STOPPED: run this inside the GitHub repo folder"; exit 1; }
fail() { echo; echo "STOPPED: $1"; exit 1; }

echo "== Adding the static-site files"
echo "" | base64 -d | tar xzf - || fail "couldn't unpack the files"
rm -f deploy_hf.sh

echo "== Building the site from your AI-explained match"
python build_static.py || fail "build failed (see above)"

REMOTE=$(git -C "$ROOT" remote get-url origin)
SLUG=$(echo "$REMOTE" | sed -E 's#(https://github.com/|git@github.com:)##; s#\.git$##')
OWNER=${SLUG%%/*}; REPO=${SLUG#*/}
URL="https://$(echo "$OWNER" | tr 'A-Z' 'a-z').github.io/$REPO/"

echo "== Updating README, SUBMISSION and VIDEO_SCRIPT"
cd "$ROOT"
sed -i "s#_add your Azure Container Apps link here_#$URL (replays a match explained by the agents, in the browser; the live AI features are shown in the video)#; s#_Azure Container Apps link_#$URL#" README.md SUBMISSION.md
sed -i 's#Render & Personalize: Azure Container Apps#Render \& Personalize: web app#' README.md
sed -i 's#^- \*\*Azure Container Apps\*\*: hosts the web app, with the API key stored as a secret#- **Hosting**: the public demo is an in-browser replay of an AI-explained match on GitHub Pages (`build_static.py`). The full app with live agents runs with `uvicorn`, and `deploy_azure.sh` deploys it to Azure Container Apps with the key stored as a secret#' README.md
sed -i 's#^- \*\*Azure Container Apps\*\*: hosts the live web app; the API key is stored as a secret\.#- **Hosting**: the public demo replays an AI-explained match in the browser (GitHub Pages). The full app with live agents runs on FastAPI, with a ready-made Azure Container Apps deployment script.#' SUBMISSION.md
sed -i 's#Microsoft Foundry, Agent Framework, Azure Container Apps, built with GitHub Copilot\.#Microsoft Foundry and Agent Framework, built in GitHub Codespaces with GitHub Copilot.#' VIDEO_SCRIPT.md
sed -i 's#^- Open your live demo link in a fresh browser window, full screen\.#- In the codespace, from matchsim, run `uvicorn app.server:app --port 8000`, open the Ports tab and click the globe next to 8000, so the AI features work live. Full screen.#' VIDEO_SCRIPT.md

echo "== Saving to GitHub"
git add -A
git diff --cached --quiet || git commit -q -m "Free live demo on GitHub Pages"
git push -q || fail "git push failed (see above)"
echo "   saved"

echo "== Turning on GitHub Pages"
if gh api -X POST "repos/$OWNER/$REPO/pages" -f "source[branch]=main" -f "source[path]=/docs" >/dev/null 2>&1 \
   || gh api -X PUT "repos/$OWNER/$REPO/pages" -f "source[branch]=main" -f "source[path]=/docs" >/dev/null 2>&1; then
  echo "   done"
else
  echo
  echo "   Do this one step in your browser (the script will wait):"
  echo "   https://github.com/$OWNER/$REPO/settings/pages"
  echo "   Under 'Build and deployment': Source = Deploy from a branch, Branch = main, folder = /docs, then Save."
fi

echo; echo "== Waiting for the site to go live (1-5 minutes)"
for i in $(seq 1 60); do
  if curl -sf -o /dev/null "${URL}data/match.json"; then
    echo
    echo "=============================================================="
    echo " Live demo:  $URL"
    echo " 1. Open it in a private window and press Start match."
    echo " 2. Record the video (VIDEO_SCRIPT.md), upload to YouTube as Public or Unlisted."
    echo " 3. Run:  bash finish.sh --video https://youtu.be/your-video"
    echo " 4. Copy SUBMISSION.md into https://aka.ms/insidethegame and submit."
    echo "=============================================================="
    exit 0
  fi
  printf "."; sleep 10
done
fail "the site isn't up yet. Check https://github.com/$OWNER/$REPO/settings/pages, then open $URL in a few minutes"
